      @description = description
      @events = events
      @format = format
      @id = id
      @status = status
      @url = url
      freeze
    end

    # Builds a WebhookEndpoint from the API's JSON.
    def self.from_hash(data)
      new(
        consecutive_failures: data.fetch("consecutive_failures"),
        created_at: data.fetch("created_at"),
        description: data.fetch("description"),
        events: data.fetch("events"),
        format: data.fetch("format"),
        id: data.fetch("id"),
        status: data.fetch("status"),
        url: data.fetch("url")
      )
    end
  end

